function updateExecutionControls(){
  const api=apiMode(), live=$('runMode').value==='openai-live', ready=Boolean(S.verified), a=S.api;
  const supported=Array.isArray(a.planning_modes)&&a.planning_modes.includes('live')&&Number(a.live_b_overhead_calls)===3;
  $('apiAccessField').hidden=!api&&!S.apiPending;
  $('executionNotice').textContent=live?'Real OpenAI Planning, Risk and independent B Critic calls precede the report Writer and Critic. Only verified published course excerpts are sent. One report-review round reserves up to 5 calls, two rounds up to 7. B must pass before C starts. No Jira writes or human approval occur.':api?'Real OpenAI calls use the server-side key and may incur usage. Only the published course excerpts and validated rule-based planning/risk context are sent. The access code is not an API key and is never saved.':'Free mode recomputes evidence excerpts and rules in your browser. No paid model calls.';
  $('runButton').textContent=S.busy?(api?'Generating and reviewing…':'Running evidence demo…'):(live?'Generate planning + report ↗':api?'Generate with OpenAI ↗':'Run live demo ↗');
  const allowance=apiRoundAllowance();
  $('runButton').disabled=S.busy||!ready||(api&&(!a.configured||allowance<1||!$('apiAccessCode').value.trim()||live&&!supported));
  $('runMode').disabled=S.busy;
  $('apiAccessCode').disabled=S.busy;
  const rounds=$('runForm').elements.max_review_rounds;
  const maximum=api?allowance:5;
  rounds.disabled=api&&maximum===0;
  for(const option of rounds.options)option.disabled=Number(option.value)>maximum;
  if(maximum>0&&Number(rounds.value)>maximum)rounds.value=String(maximum);
  const selectedRounds=Number(rounds.value)||1;
  $('runHint').textContent=live?`B Planning + Risk + B Critic, then Writer + Critic · Up to ${3+2*Math.min(selectedRounds,2)} API calls`:api?'Server-side Writer + Critic · 2 calls per report-review round':'Real browser execution · No paid API calls';
  if(a.configured){
    const minimum=live?5:2;
    $('apiStatus').textContent=live&&!supported?'The deployed server has not enabled the new B route. Report-only API and free mode remain available.':a.remaining_calls!=null&&Number(a.remaining_calls)<minimum?`The remaining server allowance cannot cover this route (minimum ${minimum} calls). Existing results, pending-result recovery and free mode remain available.`:`OpenAI ready${a.model?' · '+a.model:''}${a.remaining_calls==null?'':' · '+a.remaining_calls+' calls remaining in the server allowance'}. Access code required.`;
  }
  $('apiPending').hidden=!S.apiPending;
}
function apiRoundAllowance(){
  const serverMaximum=Math.min(2,Number(S.api.max_review_rounds)||2);
  const live=$('runMode').value==='openai-live';
  if(live&&(!Array.isArray(S.api.planning_modes)||!S.api.planning_modes.includes('live')||Number(S.api.live_b_overhead_calls)!==3))return 0;
  if(S.api.remaining_calls==null)return serverMaximum;
  const overhead=live?3:0;
  return Math.max(0,Math.min(serverMaximum,Math.floor((Number(S.api.remaining_calls)-overhead)/2)||0));
}
function onRunModeChange(){
  if($('runMode').value==='openai-live')$('runForm').elements.max_review_rounds.value='1';
  updateExecutionControls();
}

function apiAttemptStopped(record){
  return record?.api_details?.completed===false||!record?.full?.reporting?.reports?.length||!record?.full?.reporting?.critic_reviews?.length;
}
function apiRunSummary(record){
  const reporting=record?.full?.reporting||{},report=reporting.reports?.[0],reviews=reporting.critic_reviews||[];
  if(record?.api_details?.planning_mode==='live'&&record?.api_details?.b_agent?.status!=='VALIDATED')return 'B planning/risk did not complete a validated handoff. Provisional candidates and the B review are retained. C did not generate a report from unvalidated B output.';
  if(!report)return 'This API attempt produced no validated report. No completed Critic review is recorded. Inspect the retained error and attempted usage.';
  if(!reviews.length)return 'A Writer draft is retained, but no completed Critic review is recorded. Inspect the retained status and any error; the draft is not approved for release.';
  if(record.api_details?.completed===false)return 'A Writer draft and '+reviews.length+' completed Critic review(s) are retained, but a later API stage stopped. Inspect the error and attempted usage; no release approval is granted.';
  return (record?.api_details?.planning_mode==='live'?'B passed its independent review and A validation before C. ':'')+'A narrative draft and '+reviews.length+' separate Critic review(s) were recorded by the live server-side OpenAI workflow. The recorded verdict and human release checkpoint remain visible.';
}
function setApiPending(pending){
  S.apiPending=pending?{key:pending.key,fingerprint:pending.fingerprint}:null;
  try{if(S.apiPending)sessionStorage.setItem(API_PENDING_SESSION,JSON.stringify(S.apiPending));else sessionStorage.removeItem(API_PENDING_SESSION);}catch{}
}
function restoreApiPending(){
  try{
    const pending=JSON.parse(sessionStorage.getItem(API_PENDING_SESSION)||'null');
    if(pending&&typeof pending.key==='string'&&/^[A-Za-z0-9_-]{8,100}$/.test(pending.key)&&typeof pending.fingerprint==='string'&&pending.fingerprint.length<=5000){
      const input=JSON.parse(pending.fingerprint);
      if(input&&typeof input==='object'&&!Array.isArray(input)&&Object.keys(input).every(key=>['report_type','start_date','end_date','as_of_date','max_review_rounds','delay_weeks','extra_cost_sgd','planning_mode'].includes(key)))S.apiPending={key:pending.key,fingerprint:pending.fingerprint};
    }
  }catch{}
}
async function refreshApiStatus(){
  try{
    const response=await fetch('/api/status',{cache:'no-store'});
    if(!response.ok)throw Error('The API service is unavailable. Free mode remains available.');
    const data=await response.json();
    S.api={configured:data.configured===true,model:data.model||null,remaining_calls:data.remaining_calls??null,max_review_rounds:data.max_review_rounds||2,planning_modes:Array.isArray(data.planning_modes)?data.planning_modes:[],live_b_overhead_calls:Number(data.live_b_overhead_calls)||0,message:data.message||''};
    $('apiStatus').textContent=S.api.configured&&S.api.remaining_calls!=null&&S.api.remaining_calls<2?'The remaining server allowance cannot cover a Writer + Critic pair. Existing results, pending-result recovery and free mode remain available.':S.api.configured?`OpenAI ready${S.api.model?' · '+S.api.model:''}${S.api.remaining_calls==null?'':' · '+S.api.remaining_calls+' calls remaining in the server allowance'}. Access code required.`:(S.api.message||'API configuration is not ready. Free mode remains available.');
  }catch(error){S.api.configured=false;$('apiStatus').textContent=error.message||'Could not check the API service. Free mode remains available.';}
  $('runMode').querySelector('option[value="openai"]').disabled=!S.api.configured;
  $('runMode').querySelector('option[value="openai-live"]').disabled=!S.api.configured||!S.api.planning_modes.includes('live')||S.api.live_b_overhead_calls!==3;
  updateExecutionControls();
}
function waitingForApi(){
  $('jobPanel').hidden=false;
  $('jobPanel').innerHTML=$('runMode').value==='openai-live'?'<div class="job-top"><h3>OpenAI planning and reporting</h3><span>Waiting for Planning, Risk and B Critic, then C Writer and Critic</span></div><p>The server generates B from verified published excerpts and checks the proposal before C starts. One report-review round reserves up to 5 calls. This can take several minutes. No simulated progress is shown; actual trace events arrive with the result.</p>':'<div class="job-top"><h3>OpenAI report generation</h3><span>Waiting for the server-side Writer and Critic</span></div><p>The server validates evidence, writes a narrative draft and reviews it. This can take a minute or longer. No simulated progress is shown; actual trace events arrive with the result.</p>';
}
function acceptLiveRecord(view){
  // Local Harbourline server: lines the B agent cited from the verified local library are
  // returned with the run and added to the evidence map before the same citation check.
  if(view.evidence_additions)Object.assign(S.data.extra_evidence??={},view.evidence_additions);
  S.engine.checkEvidence(view.full,S.data);
  S.record=view;S.critic=null;S.query=null;S.report=0;S.view='overview';
  S.events=view.trace||[];if(S.events.length)jobPanel();
  remember(view);setHash();render();
}
async function runApi(input){
  if(!S.api.configured)throw Error('The API service is not configured. No request was sent.');
  const access=$('apiAccessCode').value.trim();
  if(!access||/^sk-/i.test(access))throw Error('Enter the presentation access code. Do not enter an OpenAI API key.');
  const fingerprint=JSON.stringify(input);
  if(S.apiPending&&S.apiPending.fingerprint!==fingerprint)throw Error('A previous API request is still unresolved. Check its pending result before changing inputs and starting another paid run.');
  const key=S.apiPending?.key||crypto.randomUUID();
  setApiPending({key,fingerprint});updateExecutionControls();waitingForApi();
  let response,payload;
  try{
    response=await fetch('/api/runs',{method:'POST',headers:{'Content-Type':'application/json','X-Demo-Access':access,'Idempotency-Key':key},body:JSON.stringify(input),signal:AbortSignal.timeout(input.planning_mode==='live'?660000:240000)});
    payload=await response.json();
  }catch(error){throw Error('The API result could not be confirmed. The server may still be working. Use “Check pending result” before starting another request.');}
  const pending=['RUNNING','IN_PROGRESS'].includes(payload.status)||['RUNNING','IN_PROGRESS'].includes(payload.error?.code);
  if(payload.run)acceptLiveRecord(payload.run);
  if(pending){message('The API run is still in progress. Any checkpoint draft is provisional. Use “Check pending result”; no new generation is needed.');return null;}
  const terminal=['COMPLETE','FAILED'].includes(payload.status)||Boolean(payload.run);
  const rejected=['ACCESS_REQUIRED','ORIGIN_REJECTED','API_NOT_CONFIGURED','IDEMPOTENCY_REQUIRED','INVALID_INPUT','INVALID_ROUNDS','INVALID_SETTINGS','BODY_TOO_LARGE','RUN_IN_PROGRESS','CALL_LIMIT_REACHED'].includes(payload.error?.code);
  if(terminal||rejected)setApiPending(null);
  if(!response.ok||payload.error)throw Error(payload.error?.message||'The API run stopped. Any returned draft and measured usage have been retained.');
  if(!payload.run)throw Error('The API result could not be confirmed. Check the pending result before starting another request.');
  message(apiAttemptStopped(payload.run)?'API attempt stopped before the complete Writer–Critic workflow finished. '+apiRunSummary(payload.run):'Live OpenAI review completed at its recorded verdict. The draft and measured usage are retained; human release approval remains required.',apiAttemptStopped(payload.run));
  return payload.run;
}
async function resumeApi(){
  if(S.busy||!S.apiPending)return;
  const access=$('apiAccessCode').value.trim();if(!access||/^sk-/i.test(access)){message('Enter the presentation access code to check the pending result. Do not enter an OpenAI API key.',true);return;}
  S.busy=true;updateExecutionControls();
  try{
    const response=await fetch('/api/runs/'+encodeURIComponent(S.apiPending.key),{headers:{'X-Demo-Access':access},cache:'no-store'});
    const payload=await response.json();
    if(payload.run)acceptLiveRecord(payload.run);
    if(['RUNNING','IN_PROGRESS'].includes(payload.status)||payload.error?.code==='RUNNING')message('The existing API run is still in progress. Any checkpoint draft is provisional; the request reference is retained.');
    else if(['COMPLETE','FAILED'].includes(payload.status)||payload.run){setApiPending(null);message(payload.error?.message||(payload.run&&apiAttemptStopped(payload.run)?'The saved API attempt stopped. '+apiRunSummary(payload.run):'The server result has been recovered. No new generation was requested.'),payload.status==='FAILED'||Boolean(payload.run&&apiAttemptStopped(payload.run)));}
    else if(response.status===404&&payload.error?.code==='NOT_FOUND'){setApiPending(null);message('The server has no matching run. You can submit the selected inputs again.');}
    else throw Error(payload.error?.message||'The pending result could not be confirmed.');
  }catch(error){message(error.message||'Could not recover the pending result.',true);}
  finally{S.busy=false;await refreshApiStatus();updateExecutionControls();}
}
async function run(event){
  event?.preventDefault();if(S.busy)return;S.busy=true;S.events=[];updateExecutionControls();message('');
  try{
    if(apiMode())await runApi(inputValues());
    else{
      const view=await S.engine.runPresentation(S.data,inputValues(),e=>{S.events.push(e);jobPanel();});
      acceptLiveRecord(view);message('Free live run complete. The evidence report and trace were computed in this browser; human review remains required.');
    }
    $('runContext').scrollIntoView({behavior:'smooth',block:'start'});
  }catch(error){message(error.message||'The live run stopped.',true);}
  finally{S.busy=false;await refreshApiStatus();updateExecutionControls();}
}

async function query(text){if(S.busy){message('Please wait for the current operation.');return;}S.busy=true;S.queryText=text;S.query=null;render();try{S.query=await S.engine.retrieve(S.data,{question:text,as_of_date:$('asOfDate').value});message('');}catch(e){message(e.message||'Retrieval stopped.',true);}finally{S.busy=false;render();}}
async function test(action){if(S.busy)return;if(!S.record){message('Run a live demo first.',true);return;}S.busy=true;render();try{if(action==='change-test'){const result=await S.engine.applyChange(S.data,S.record);S.record=result.run;S.critic=null;remember(S.record);S.view='governance';setHash();message(result.notice);}else{if(S.record.provider==='openai')throw Error('Use free mode for the isolated quote-only test. This test does not evaluate a generated narrative.');S.critic=await S.engine.runCriticTest(S.data,S.record);message(S.critic.notice);}}catch(e){message(e.message||'The TEST operation stopped.',true);}finally{S.busy=false;render();}}
async function source(ref){const dialog=$('evidenceDialog');$('evidenceContent').textContent='Checking the saved excerpt coordinates…';dialog.showModal();try{const d=S.engine.resolveEvidence?await S.engine.resolveEvidence(ref,S.data):S.data.evidence[JSON.stringify([ref.document_id,ref.document_version,ref.page,ref.line_start,ref.line_end])];if(!d)throw Error('This exact excerpt is not loaded.');$('evidenceContent').innerHTML=`<div class="evidence-meta"><strong>${esc(d.document_id)}</strong><p>Version ${esc(d.version||ref.document_version)} · ${d.page==null?'Text source':`page ${d.page}`} · L${d.start??ref.line_start}–${d.end??ref.line_end}</p></div><div class="evidence-quote">${esc(ref.quote)}</div><h3 class="source-lines-heading">Saved original source lines</h3><div class="source-lines">${d.lines.map(l=>`<div class="source-line cited"><span class="line-number">${l.number}</span><span class="line-text">${esc(l.text)}</span></div>`).join('')}</div><p class="evidence-foot">The exported excerpt was verified against the physical course source before publication. Live checks validate the loaded excerpt and its quotation; this browser does not reopen the original PDF.</p>`;}catch(e){$('evidenceContent').textContent=e.message;}}
function exportRecord(){if(!S.record)return;const blob=new Blob([JSON.stringify(S.record,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='harbourline-presentation-'+S.record.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function printReport(){
  const record=S.record,report=record?.full.reporting.reports[Math.min(S.report,record.full.reporting.reports.length-1)];
  if(!report){message('There is no report to print.',true);return;}
  const reviews=record.full.reporting.critic_reviews.filter(review=>review.report_id===report.report_id);
  let paper=$('reportPrint');if(!paper){paper=document.createElement('section');paper.id='reportPrint';document.body.append(paper);}
  paper.innerHTML=`<header><p>HARBOURLINE COMMUNITY HUB / MA6094</p><h1>${esc(report.report_type==='MONTHLY_GRANT'?'Monthly grant report':'Weekly committee update')}</h1><p>${esc(recordMode(record))}</p></header><dl><dt>Status</dt><dd>${esc(label(report.status))}${report.is_stale?' · STALE':''} · Not approved for release</dd><dt>Period</dt><dd>${esc(report.reporting_period.start_date)} to ${esc(report.reporting_period.end_date)}</dd><dt>Evidence cut-off</dt><dd>${esc(record.as_of_date||'Not recorded')}</dd><dt>Run</dt><dd>${esc(record.id)}</dd></dl>${report.sections.map(section=>`<section><h2>${esc(section.heading)}</h2><p class="print-narrative">${esc(section.text)}</p>${(section.citations||[]).map(ref=>`<blockquote><strong>${esc(sourceLabel(ref))} · version ${esc(ref.document_version)}</strong><p>${esc(ref.quote)}</p></blockquote>`).join('')}</section>`).join('')}<section><h2>Open issues</h2>${list(report.open_issues)}<h2>Assumptions</h2>${list(report.assumptions)}</section><section><h2>Critic review history</h2>${reviews.map(review=>`<h3>Round ${esc(review.review_round)}: ${esc(review.verdict)} / ${esc(review.stop_reason)}</h3>${list(review.findings.map(finding=>finding.description+' Required fix: '+finding.required_fix))}`).join('')||'<p>No completed Critic review is available.</p>'}</section><footer><p>Fictional course project. Source matching and Critic review do not confer human approval. API calls: ${esc(num(record.full.metrics.api_calls))}; input / output tokens: ${esc(num(record.full.metrics.input_tokens))} / ${esc(num(record.full.metrics.output_tokens))}; API cost (USD): ${esc(money(record.full.metrics.estimated_cost_usd))}.</p></footer>`;
  document.body.classList.add('printing-report');window.print();
}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing-report'));

function reset(){if(S.busy){message('Wait for the current operation before resetting.');return;}if(S.apiPending){message('Check the unresolved API result before resetting, so a running paid request is not lost.',true);return;}$('apiAccessCode').value='';S.liveRuns={};try{sessionStorage.removeItem(SESSION);}catch{}S.record=null;S.query=null;S.critic=null;S.events=[];S.view='overview';$('jobPanel').hidden=true;$('recordBadge').textContent='Choose inputs and run';fillHistory();setHash();render();updateExecutionControls();message('Demo session reset. Saved source data and historical comparisons are unchanged.');$('runForm').scrollIntoView({behavior:'smooth',block:'center'});}
document.addEventListener('click',event=>{const b=event.target.closest('button,[data-view],a[data-action]');if(!b)return;if(b.dataset.view){selectView(b.dataset.view);return;}const a=b.dataset.action;if(a==='ce-write'){writeChangeNote(b.dataset.event);return;}if(a==='evidence')source(S.refs[Number(b.dataset.ref)]);else if(a==='show-guide')$('guideDialog').showModal();else if(a==='close-guide')$('guideDialog').close();else if(a==='close-evidence')$('evidenceDialog').close();else if(a==='view-reports')selectView('reports');else if(a==='view-memory')selectView('memory');else if(a==='run-now')$('runForm').requestSubmit();else if(a==='query-budget')query('What is the approved budget for Harbourline Community Hub?');else if(a==='query-absent')query('What is the name of the pet dragon kept in Harbourline Community Hub?');else if(a==='query-asbestos')query('What is documented about asbestos and its schedule impact?');else if(a==='critic-test'||a==='change-test')test(a);else if(a==='export-record')exportRecord();else if(a==='print-report')printReport();else if(a==='refresh-api')refreshApiStatus();else if(a==='resume-api')resumeApi();else if(a==='reset-demo')reset();else if(a==='presentation'){document.body.classList.toggle('presentation-mode');b.textContent=document.body.classList.contains('presentation-mode')?'Show full controls':'Presentation view';}else if(a==='home'){event.preventDefault();S.view='overview';setHash();render();window.scrollTo({top:0,behavior:'smooth'});}});
document.addEventListener('submit',event=>{if(event.target.id==='queryForm'){event.preventDefault();query($('queryText').value);}});
document.addEventListener('input',event=>{if(event.target.id==='planSearch'){const pos=event.target.selectionStart;S.search=event.target.value;render();const next=$('planSearch');next.focus();next.setSelectionRange(pos,pos);}if(event.target.id==='queryText')S.queryText=event.target.value;});
$('runMode').addEventListener('change',onRunModeChange);$('apiAccessCode').addEventListener('input',updateExecutionControls);
$('runForm').addEventListener('submit',run);$('historySelect').addEventListener('change',event=>{try{loadRecord(event.target.value);}catch(e){message(e.message,true);}});$('reportType').addEventListener('change',()=>{const p=S.boot.defaults[$('reportType').value==='MONTHLY_GRANT'?'monthly':'weekly'];$('startDate').value=p.start_date;$('endDate').value=p.end_date;});
for(const id of ['guideDialog','evidenceDialog'])$(id).addEventListener('click',event=>{if(event.target===$(id))$(id).close();});
window.addEventListener('hashchange',()=>{if(!S.data)return;const p=new URLSearchParams(location.hash.slice(1));S.view=VIEWS.includes(p.get('view'))?p.get('view'):'overview';const id=p.get('run');try{if(id&&id!==S.record?.id&&(S.liveRuns[id]||S.data.runs[id]))loadRecord(id);else render();}catch(e){message(e.message,true);}});
(async()=>{try{const [response,engine]=await Promise.all([fetch('/data/presentation-data.json'),import('/engine.mjs')]);if(!response.ok)throw Error('The presentation evidence could not be loaded.');S.data=await response.json();S.engine=engine;S.verified=await engine.verifyCorpus(S.data);S.boot=structuredClone(S.data.bootstrap);$('snapshotTag').textContent='Verified excerpts · '+S.boot.project.snapshot;$('sidebarJira').href=S.boot.jira.url;try{const saved=JSON.parse(sessionStorage.getItem(SESSION)||'{}');for(const [id,r]of Object.entries(saved)){if(r?.mode==='live'&&(r.full?.source_snapshot_id===S.boot.project.snapshot||r.evidence_additions)){if(r.evidence_additions)Object.assign(S.data.extra_evidence??={},r.evidence_additions);engine.checkEvidence(r.full,S.data);S.liveRuns[id]=r;}}}catch{S.liveRuns={};}const hash=new URLSearchParams(location.hash.slice(1));S.view=VIEWS.includes(hash.get('view'))?hash.get('view'):'overview';const id=hash.get('run');if(id&&(S.liveRuns[id]||S.data.runs[id]))S.record=structuredClone(S.liveRuns[id]||S.data.runs[id]);restoreApiPending();fillHistory();render();updateExecutionControls();refreshApiStatus();loadLocalRuns();}catch(e){message(e.message||'The presentation could not start.',true);$('workspace').innerHTML=note('The source integrity check did not complete. Live execution is disabled until the loaded evidence is verified.','blocked');}})();
